sys_script_include.script:
var StudentRefQual = Class.create();
StudentRefQual.prototype = {

    initialize: function() {},

    // --------------------------------------------------
    // COMMON HELPER: GET STUDENT EMAIL
    // --------------------------------------------------

    getStudentEmail: function(studentGR) {

        if (!studentGR || !studentGR.isValidRecord()) {
            return '';
        }

        var userId = studentGR.getValue('user');

        if (!userId) {
            return '';
        }

        var userGR = new GlideRecord('sys_user');

        if (!userGR.get(userId)) {
            return '';
        }

        return userGR.getValue('email') || '';
    },


    // --------------------------------------------------
    // 1. STUDENT - SECTION REFERENCE QUALIFIER
    // --------------------------------------------------
    // Filters sections based on student's college
    // and program.
    // --------------------------------------------------

    getSections: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var collegeId = current.getValue('college');
        var programId = current.getValue('program');

        if (!collegeId || !programId) {
            return noRecords;
        }

        var sectionGR = new GlideRecord(
            'x_1790229_edusph_0_section'
        );

        sectionGR.addQuery('college', collegeId);
        sectionGR.addQuery('program', programId);
        sectionGR.query();

        var sectionIds = [];

        while (sectionGR.next()) {
            sectionIds.push(sectionGR.getUniqueValue());
        }

        if (sectionIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + sectionIds.join(',');
    },


    // --------------------------------------------------
    // 2. STUDENT - ADMISSION APPLICATION QUALIFIER
    // --------------------------------------------------
    // Filters admission applications using the email
    // address of the student's associated User record.
    // --------------------------------------------------

    getAdmissionApplications: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var email = this.getStudentEmail(current);

        if (!email) {
            return noRecords;
        }

        var applicationGR = new GlideRecord(
            'x_1790229_edusph_0_admission_application'
        );

        applicationGR.addQuery('email', email);
        applicationGR.query();

        var applicationIds = [];

        while (applicationGR.next()) {
            applicationIds.push(
                applicationGR.getUniqueValue()
            );
        }

        if (applicationIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + applicationIds.join(',');
    },


    // --------------------------------------------------
    // 3. STUDENT DOCUMENT - APPLICATION QUALIFIER
    // --------------------------------------------------
    // Retrieves the selected Student's email through
    // the associated User record and filters admission
    // applications using that email.
    // --------------------------------------------------

    getDocumentApplications: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var studentId = current.getValue('student');

        if (!studentId) {
            return noRecords;
        }

        // Retrieve selected Student
        var studentGR = new GlideRecord(
            'x_1790229_edusph_0_student'
        );

        if (!studentGR.get(studentId)) {
            return noRecords;
        }

        // Get student's email
        var email = this.getStudentEmail(studentGR);

        if (!email) {
            return noRecords;
        }

        // Find matching admission applications
        var applicationGR = new GlideRecord(
            'x_1790229_edusph_0_admission_application'
        );

        applicationGR.addQuery('email', email);
        applicationGR.query();

        var applicationIds = [];

        while (applicationGR.next()) {
            applicationIds.push(
                applicationGR.getUniqueValue()
            );
        }

        if (applicationIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + applicationIds.join(',');
    },

	// find semester according to program 

	getSemesterByProgram: function(current) {

    var programId = current.getValue('program');

    if (!programId) {
        return 'sys_idINempty';
    }

    var semesterIds = [];

    var semesterGR = new GlideRecord('x_1790229_edusph_0_semester');
    semesterGR.addQuery('program', programId);
    semesterGR.query();

    while (semesterGR.next()) {
        semesterIds.push(semesterGR.getUniqueValue());
    }

    return semesterIds.length > 0 ?
        'sys_idIN' + semesterIds.join(',') :
        'sys_idINempty';
},


        getProgramsForStudent: function(current) {
        var collegeId = '';
        if (current && current.getValue('college')) {
            collegeId = current.getValue('college');
        } else {
            collegeId = new x_1790229_edusph_0.ERPSecurityUtils().getUserCollege();
        }
        if (!collegeId) {
            if (new x_1790229_edusph_0.ERPSecurityUtils().isUniversityLeadership()) {
                return 'status=active';
            }
            return 'sys_idISEMPTY';
        }
        var cpGR = new GlideRecord('x_1790229_edusph_0_coll_prog');
        cpGR.addQuery('college', collegeId);
        cpGR.query();
        var progIds = [];
        while (cpGR.next()) {
            var p = cpGR.getValue('program');
            if (p && progIds.indexOf(p) === -1) {
                progIds.push(p);
            }
        }
        if (progIds.length === 0) {
            return 'sys_idISEMPTY';
        }
        return 'sys_idIN' + progIds.join(',');
    },

    type: 'StudentRefQual'
};
